<template>
 <div class="app-container platform-log-center">
  <div class="page-heading"><p class="muted">支持按订单、发货单与换货单追溯；重试与核对请从原业务单据操作。</p><el-button size="small" icon="el-icon-refresh" :loading="loading" @click="search">刷新</el-button></div>
  <el-tabs :value="query.category || 'ALL'" class="business-tabs" @tab-click="tabChanged"><el-tab-pane v-for="item in businessTabs" :key="item.key" :name="item.key" :label="item.label" /></el-tabs>
  <el-form inline size="small" class="filters" @submit.native.prevent="search">
   <el-form-item label="业务单号"><el-input v-model.trim="query.number" clearable maxlength="128" placeholder="输入完整订单号、换货单号或发货单号" class="number-input" @input="numberChanged" @keyup.enter.native="search" /></el-form-item>
   <el-form-item label="店铺"><el-select v-model="query.channelId" clearable filterable placeholder="全部店铺"><el-option v-for="shop in options.shops || []" :key="shop.channel_id" :value="String(shop.channel_id)" :label="shop.channel_name + (Number(shop.enabled) ? '' : '（已停用）')" /></el-select></el-form-item>
   <el-form-item label="业务分类"><el-select v-model="query.category" clearable @change="categoryChanged"><el-option v-for="(name,key) in categories" :key="key" :label="name" :value="key" /></el-select></el-form-item>
   <el-form-item label="业务动作"><el-select v-model="query.method" clearable filterable placeholder="选择中文业务动作"><el-option v-for="item in availableActions" :key="item.method" :label="item.label" :value="item.method" /></el-select></el-form-item>
   <el-form-item label="本次结果"><el-select v-model="query.result" clearable><el-option v-for="(name,key) in results" :key="key" :label="name" :value="key" /></el-select></el-form-item>
   <el-form-item label="时间"><el-date-picker v-model="range" type="datetimerange" value-format="yyyy-MM-dd HH:mm:ss" start-placeholder="开始时间" end-placeholder="结束时间" :disabled="query.allTime" /></el-form-item><el-form-item><el-checkbox v-model="query.allTime" :disabled="!query.number && !query.requestId">本单全部时间</el-checkbox></el-form-item>
   <el-form-item><el-button type="primary" icon="el-icon-search" @click="search">查询</el-button><el-button @click="reset">重置</el-button><el-button type="text" @click="advanced=!advanced">{{ advanced ? '收起筛选' : '更多筛选' }}</el-button></el-form-item>
   <template v-if="advanced"><el-form-item label="单号类型"><el-select v-model="query.numberType"><el-option v-for="(name,key) in numberTypes" :key="key" :label="name" :value="key" /></el-select></el-form-item><el-form-item label="记录类型"><el-select v-model="query.entryKind" clearable><el-option v-for="(name,key) in kinds" :key="key" :label="name" :value="key" /></el-select></el-form-item><el-form-item label="环境"><el-select v-model="query.environment" clearable><el-option v-for="(name,key) in environments" :key="key" :label="name" :value="key" /></el-select></el-form-item><el-form-item label="接口名"><el-input v-model.trim="query.method" clearable placeholder="完整接口英文名称" /></el-form-item><el-form-item label="请求编号"><el-input v-model.trim="query.requestId" clearable maxlength="64" placeholder="日志请求 / 链路 / 业务请求编号" /></el-form-item><el-form-item label="触发来源"><el-select v-model="query.triggerSource" clearable><el-option v-for="(name,key) in triggers" :key="key" :label="name" :value="key" /></el-select></el-form-item></template>
  </el-form>
  <div class="quick-filters"><span class="muted">快捷查看</span><el-button size="mini" @click="quick('result','FAILED')">失败</el-button><el-button size="mini" @click="quick('result','UNKNOWN')">结果待确认</el-button><el-button size="mini" @click="quick('environment','SIMULATION')">模拟记录</el-button><el-button size="mini" @click="quick('entryKind','CONFIG')">配置操作</el-button></div>
  <div v-if="contextNumber" class="business-context" v-loading="contextLoading"><div class="context-heading"><strong>该单平台处理说明</strong><span class="muted">{{ contextNumber }} · 当前业务状态，独立于下方调用记录</span></div><el-alert v-if="contextError" :title="contextError" type="info" :closable="false" /><exchange-platform-status v-for="item in contexts" :key="item.id" :exchange="item" :show-logs="false"><el-button type="text" @click="openExchange(item)">查看换货单 {{ item.exchange_sn }}</el-button></exchange-platform-status><p v-if="!contextLoading && !contexts.length && !contextError" class="muted">未找到可展示的换货处理单；下方继续按关联业务单号查询接口记录。</p><el-alert v-if="contextTruncated" title="关联换货单较多，显示前20张；请使用具体换货单号精确查询。" type="info" :closable="false" /></div>
  <div class="counts"><div v-for="(name,key) in results" :key="key" :class="key"><span>{{ name }}记录</span><strong>{{ counts[key] == null ? '—' : counts[key] }}</strong></div></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" /><el-alert v-if="stateError" :title="stateError" type="info" :closable="false" />
  <el-table v-loading="loading" :data="rows" row-key="id" :empty-text="error ? '加载失败，请重新查询' : '未检索到符合条件的调用记录；可查看上方平台处理说明，或清除动作、结果等筛选后重查'">
   <el-table-column label="时间 / 店铺" min-width="190"><template slot-scope="s"><div>{{ s.row.create_time }}</div><div>{{ s.row.channel_name || '应用配置' }}</div><div class="muted">天猫 · {{ triggers[s.row.trigger_source] || s.row.trigger_source }}</div></template></el-table-column>
   <el-table-column label="业务动作 / 环境" min-width="220"><template slot-scope="s"><strong>{{ action(s.row) }}</strong><div class="tag-line"><el-tag size="mini" :type="s.row.environment === 'SIMULATION' ? 'warning' : 'info'">{{ environments[s.row.environment] }}</el-tag><el-tag size="mini" effect="plain">{{ kinds[s.row.entry_kind] }}</el-tag></div><div class="muted">{{ categories[s.row.category] }} · {{ s.row.duration_ms }} ms</div></template></el-table-column>
   <el-table-column label="关联业务单据" min-width="280"><template slot-scope="s"><div v-for="ref in (s.row.refs || []).slice(0,2)" :key="refKey(ref)" class="reference"><span class="muted">{{ numberTypes[ref.type] }}</span><div>{{ ref.number }}</div></div><el-button v-if="s.row.refs && s.row.refs.length > 2" type="text" @click="open(s.row.id)">另 {{ s.row.refs.length-2 }} 个关联编号</el-button><span v-if="!(s.row.refs || []).length" class="muted">此操作无业务单据</span></template></el-table-column>
   <el-table-column label="本次交互结果" min-width="180"><template slot-scope="s"><el-tag size="small" :type="tone(s.row.result)">{{ results[s.row.result] }}</el-tag><div v-if="errorSummary(s.row)" class="muted">{{ errorSummary(s.row) }}</div><div v-if="s.row.error_code" class="error-code">{{ s.row.error_code }}</div><div class="muted">{{ transport(s.row) }}</div></template></el-table-column>
   <el-table-column label="当前业务进度" min-width="180"><template slot-scope="s"><template v-if="state(s.row)"><div>{{ businessLabel(state(s.row)) }}</div><el-button type="text" @click="business(s.row)">查看关联业务</el-button></template><span v-else class="muted">{{ stateError ? '暂未查询成功' : multipleBusinesses(s.row) ? '涉及多笔业务，请查看关联编号' : (s.row.refs || []).length ? '暂无本地处理状态' : '不涉及业务进度' }}</span></template></el-table-column>
   <el-table-column label="操作" width="105" fixed="right"><template slot-scope="s"><el-button type="text" @click="open(s.row.id)">查看详情</el-button></template></el-table-column>
  </el-table>
  <div class="pagination"><span class="muted">每页 50 条 · 按时间和编号翻页</span><el-button size="small" :disabled="!history.length || loading" @click="previous">上一页</el-button><el-button size="small" :disabled="!nextCursor || loading" @click="next">下一页</el-button></div>
  <p class="muted">未输入单号时默认最近 24 小时；输入完整单号默认查询本单全部保留记录。手动时间范围最多 31 天。摘要保留 {{ options.summary_days || 90 }} 天，脱敏报文保留 {{ options.payload_days || 14 }} 天。查询不会重试或重新提交业务。</p>
  <el-drawer :visible.sync="visible" title="平台交互详情" size="min(1100px,96vw)" append-to-body :wrapper-closable="false" destroy-on-close>
   <div v-if="detail" v-loading="detailLoading" class="detail-body"><div class="detail-title"><h2>{{ action(detail) }}</h2><el-tag :type="tone(detail.result)">{{ results[detail.result] }}</el-tag><el-tag :type="detail.environment === 'SIMULATION' ? 'warning' : 'info'">{{ environments[detail.environment] }}</el-tag></div><el-alert title="本次记录反映调用当时的结果；后续查询或业务处理不会覆盖原结果。结果待确认时，请从原业务单据核对。" type="info" :closable="false" />
    <el-descriptions :column="2" border size="small"><el-descriptions-item label="请求编号">{{ detail.request_id }} <el-button v-clipboard:copy="detail.request_id" type="text" icon="el-icon-document-copy" /></el-descriptions-item><el-descriptions-item label="记录类型">{{ kinds[detail.entry_kind] }} · {{ transport(detail) }}</el-descriptions-item><el-descriptions-item label="接口名称">{{ detail.interface_name || '—' }}</el-descriptions-item><el-descriptions-item label="平台请求标识">{{ detail.platform_request_id || '平台未返回' }}</el-descriptions-item><el-descriptions-item label="开始 / 耗时">{{ detail.create_time }} / {{ detail.duration_ms }} ms</el-descriptions-item><el-descriptions-item label="触发 / 操作人">{{ triggers[detail.trigger_source] }} / {{ detail.operator }}</el-descriptions-item><el-descriptions-item label="错误码">{{ detail.error_code || '—' }}</el-descriptions-item><el-descriptions-item label="当前业务进度">{{ state(detail) ? businessLabel(state(detail)) : stateError ? '暂未查询成功' : multipleBusinesses(detail) ? '涉及多笔业务，请逐单查看' : '暂无本地处理状态' }} <el-button v-if="state(detail)" type="text" @click="business(detail)">查看关联业务</el-button></el-descriptions-item></el-descriptions>
    <h3>关联单据</h3><div class="detail-refs"><div v-for="ref in detail.refs || []" :key="refKey(ref)"><span class="muted">{{ numberTypes[ref.type] }}</span><code>{{ ref.number }}</code><el-button v-clipboard:copy="ref.number" type="text" icon="el-icon-document-copy" /></div><p v-if="!(detail.refs || []).length" class="muted">此操作未关联业务单据。</p></div>
    <h3>调用链路</h3><el-alert v-if="detail.chain_truncated" title="链路较长，仅展示最近记录及当前请求，最多100条；可按请求编号精确查询。" type="info" :closable="false" /><el-table :data="detail.chain || []" size="small"><el-table-column label="时间" prop="create_time" width="165" /><el-table-column label="动作" min-width="200"><template slot-scope="s">{{ action(s.row) }}<div class="muted">{{ kinds[s.row.entry_kind] }}</div></template></el-table-column><el-table-column label="本次结果" width="120"><template slot-scope="s"><el-tag :type="tone(s.row.result)" size="mini">{{ results[s.row.result] }}</el-tag></template></el-table-column><el-table-column label="请求编号" min-width="260"><template slot-scope="s"><el-button type="text" @click="open(s.row.id)">{{ s.row.request_id }}</el-button></template></el-table-column></el-table>
    <div class="payload-heading"><h3>脱敏请求与响应</h3><el-button v-hasPermi="['channel:platform:payload']" size="small" :loading="payloadLoading" @click="loadPayload">查看脱敏报文</el-button></div><p class="muted">凭据及未开放字段不记录，个人信息脱敏。此处为受限快照，不能直接用于重新提交。</p><el-alert v-if="payloadError" :title="payloadError" type="warning" :closable="false" /><template v-if="payload"><el-alert v-if="payload.expired" :title="payload.message" type="info" :closable="false" /><template v-else><el-alert v-if="payload.request_truncated || payload.response_truncated" title="部分字段、数组或报文大小超过限制，已截断；未记录内容不会参与业务判断。" type="warning" :closable="false" /><h4>请求</h4><pre>{{ pretty(payload.request_json) }}</pre><h4>响应</h4><pre>{{ pretty(payload.response_json) }}</pre></template></template>
   </div>
  </el-drawer>
 </div>
</template>
<script>
import ExchangePlatformStatus from '@/views/oms/order/ExchangePlatformStatus'
import { platformGet, platformPost } from '@/api/channel/platform'
import { results, kinds, categories, environments, numberTypes, actions, businessTabs, businessActions, triggers, businessStates, primaryRef, multipleBusinesses, refKey, tone, errorSummary, businessLabel } from './platformLogLabels'
const defaults = () => ({ itemId:'',skuId:'',numberType: 'AUTO', number: '', channelId: '', category: '', result: '', entryKind: '', environment: '', requestId: '', method: '', triggerSource: '', allTime: false })
export default {
 name: 'PlatformLogCenter', components: { ExchangePlatformStatus },
 data() { return { businessTabs, businessActions, contexts: [], contextNumber: '', contextError: '', contextLoading: false, contextTruncated: false, results, kinds, categories, environments, numberTypes, triggers, businessStates, query: defaults(), range: [], advanced: false, loading: false, error: '', stateError: '', states: {}, options: {}, counts: {}, rows: [], cursor: '', nextCursor: '', history: [], sequence: 0, visible: false, detail: null, detailLoading: false, detailSequence: 0, payload: null, payloadError: '', payloadLoading: false } },
 computed: { availableActions() { return this.businessActions.filter(item => !this.query.category || item.category === this.query.category) } },
 async created() { this.options = (await platformGet('/log-center/options')).data; this.fromRoute() },
 watch: { '$route.fullPath'() { this.fromRoute() } }, beforeDestroy() { this.sequence++; this.detailSequence++ },
 methods: {
  primaryRef, multipleBusinesses, refKey, tone, errorSummary, businessLabel, action(row) { return actions[row.interface_name] || actions[row.action] || row.interface_name || row.action },
  transport(row) { return row.environment === 'SIMULATION' ? '本地模拟，未请求真实平台' : row.entry_kind === 'API' ? (row.http_status ? 'HTTP ' + row.http_status : row.request_sent ? '已发送，未收到明确响应' : '未确认发送') : row.entry_kind === 'OPERATION' ? '操作汇总，接口请求见链路' : '本地处理记录' },
  fromRoute() { const q = this.$route.query; this.query = { ...defaults(), itemId:q.itemId||'',skuId:q.skuId||'',numberType: q.numberType || 'AUTO', number: q.number || '', category: q.category || '', method: q.method || '', channelId: String(q.channelId || ''), requestId: q.requestId || '', allTime: q.allTime === 'true' || (!!q.number && q.allTime !== 'false') }; this.range = []; this.search() },
  params() { return { ...this.query, start: this.range && this.range[0] || '', end: this.range && this.range[1] || '', cursor: this.cursor, limit: 50 } },
  search() { if (!this.query.number && !this.query.requestId) this.query.allTime = false; this.cursor = ''; this.history = []; return this.load(true) },
  async load(summary) { const seq = ++this.sequence; this.loading = true; this.error = ''; this.stateError = ''; const input = this.params(); if (summary) { this.contextNumber = input.number; this.contexts = []; this.contextError = ''; this.contextTruncated = false; this.contextLoading = !!input.number } try { const jobs = [platformGet('/log-center', input)]; if (summary) jobs.push(platformGet('/log-center/summary', input)); if (summary && input.number) jobs.push(platformGet('/log-center/context', { number: input.number, numberType: input.numberType }).catch(() => ({ data: { available: false, message: '该单平台处理说明暂未加载成功；可继续查看接口日志' } }))); const found = await Promise.all(jobs); if (seq !== this.sequence) return; this.rows = found[0].data.rows || []; this.nextCursor = found[0].data.next_cursor || ''; if (summary) { this.counts = found[1].data; if (input.number) { const context = found[2].data; this.contexts = context.rows || []; this.contextTruncated = context.truncated; this.contextError = context.available ? '' : context.message || '该单平台处理说明暂未加载成功' } } await this.loadStates(this.rows, seq) } catch (_) { if (seq === this.sequence) { this.rows = []; this.nextCursor = ''; this.error = '平台日志加载失败，请核对筛选条件后重新查询'; if (summary) { this.counts = {}; if (input.number) this.contextError = '查询未完成，请重新查询该单平台处理说明' } } } finally { if (seq === this.sequence) { this.loading = false; this.contextLoading = false } } },
  async loadStates(rows, seq) { const refs = [...new Map(rows.map(primaryRef).filter(Boolean).map(r => [refKey(r), r])).values()]; this.states = {}; if (!refs.length) return; try { const response = (await platformPost('/log-center/business-states', refs)).data; if (seq !== this.sequence) return; if (!response.available) { this.stateError = response.message; return } this.states = Object.fromEntries((response.rows || []).map(r => [refKey(r), r])) } catch (_) { if (seq === this.sequence) this.stateError = '当前业务进度暂未查询成功，本次接口结果仍可查看' } },
  state(row) { return this.states[refKey(primaryRef(row))] },
  business(row) { const s = this.state(row); if (!s) return; const type = s.business_type || s.type; if (type === 'EXCHANGE') this.$router.push({ path: '/oms-order/exchanges', query: { exchangeId: s.id } }); else if (type === 'SHIPMENT') this.$router.push({ path: '/oms-order/shipments', query: { number: s.number } }); else if (type === 'OMS_ORDER') this.$router.push({ path: '/oms-order/business', query: { orderId: s.id } }) },
  numberChanged(value) { this.query.allTime = !!String(value || '').trim() },
  categoryChanged() { this.query.method = '' },
  tabChanged(tab) { this.query.category = tab.name === 'ALL' ? '' : tab.name; this.categoryChanged(); return this.search() },
  openExchange(item) { this.$router.push({ path: '/oms-order/exchanges', query: { exchangeId: item.id } }) },
  reset() { this.query = defaults(); this.range = []; this.search() }, quick(key,value) { this.query[key] = value; this.search() }, next() { this.history.push(this.cursor); this.cursor = this.nextCursor; this.load(false) }, previous() { this.cursor = this.history.pop() || ''; this.load(false) },
  async open(id) { const seq = ++this.detailSequence; this.detailLoading = true; this.detail = null; this.payload = null; this.payloadError = ''; this.visible = true; try { const response = await platformGet('/log-center/' + id); if (seq === this.detailSequence) this.detail = response.data } finally { if (seq === this.detailSequence) this.detailLoading = false } },
  async loadPayload() { if (!this.detail || this.payloadLoading) return; const id = this.detail.id; this.payloadLoading = true; this.payloadError = ''; try { const response = await platformGet('/log-center/' + id + '/payload'); if (this.detail && this.detail.id === id) this.payload = response.data } catch (_) { this.payloadError = '脱敏报文暂未读取成功，请稍后重试' } finally { this.payloadLoading = false } },
  pretty(raw) { if (!raw) return '尚无报文'; try { return JSON.stringify(typeof raw === 'string' ? JSON.parse(raw) : raw, null, 2) } catch (_) { return '报文结构暂无法展示' } }
 }
}
</script>
<style scoped>
.page-heading,.detail-title,.payload-heading{display:flex;align-items:center;justify-content:space-between;gap:16px}.page-heading h2{margin:0 0 8px}.muted{color:#8290a3;font-size:12px;line-height:1.7}.business-tabs{margin-top:16px}.filters{margin-top:12px}.business-context{border-top:1px solid #e7edf5;padding-top:16px;margin:18px 0}.context-heading{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.filters .el-select{width:160px}.filters .type-select{width:145px}.number-input{width:350px;max-width:100%}.quick-filters{display:flex;gap:10px;align-items:center;margin-bottom:18px}.quick-filters .el-button{margin:0}.counts{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:18px 0}.counts>div{padding:18px 22px;border:1px solid #e1e8f0;border-radius:8px;background:#f7f9fc;display:flex;align-items:center;justify-content:space-between}.counts strong{font-size:25px}.SUCCESS strong{color:#21935b}.FAILED strong{color:#d34d45}.UNKNOWN strong{color:#b17a15}.tag-line{display:flex;gap:6px;margin:9px 0}.reference{line-height:1.5;overflow-wrap:anywhere;margin-bottom:8px}.error-code{overflow-wrap:anywhere;color:#c16b37;margin-top:8px;font-size:12px}.pagination{display:flex;gap:14px;justify-content:flex-end;align-items:center;margin:20px 0}.detail-body{padding:0 24px 30px}.detail-title{justify-content:flex-start}.detail-body .el-descriptions{margin-top:20px}.detail-body h3{margin:25px 0 15px}.detail-refs{display:grid;grid-template-columns:1fr 1fr;gap:14px}.detail-refs code{display:block;overflow-wrap:anywhere;font-family:inherit}.detail-refs>div{padding:12px;background:#f5f8fc;border-radius:5px}pre{white-space:pre-wrap;overflow-wrap:anywhere;padding:16px;background:#f5f7fa;border-radius:6px;max-height:480px;overflow:auto}.payload-heading{margin-top:20px}.el-alert{margin:14px 0}@media(max-width:1000px){.counts{grid-template-columns:1fr 1fr}.detail-refs{grid-template-columns:1fr}}
</style>
